script:
// ---------- 1) SETUP ----------
stage(1000, 600, "#030304");                          // almost black background
title({hu: "Elhagyott ház – a szoba", en: "Abandoned house – the room"}, {color: "#8d8896"});
plotWindow(30);                                        // the whole cutscene (30 s) fits in the graphs

param("bob",  {hu: "Kamera ringás (járás)", en: "Camera head-bob"}, 0, 2, 1, 0.1, "×");
param("lamp", {hu: "Zseblámpa erőssége", en: "Flashlight strength"}, 0.4, 2, 1, 0.05, "×");
toggle("jump", {hu: "Ijesztés (jumpscare) be", en: "Jumpscare on"}, true);   // off = ghost only stands there, no flash/shake
toggle("bars", {hu: "Mozifilm-sávok", en: "Letterbox bars"}, true);
toggle("caps", {hu: "Hangfelirat (nincs hang)", en: "Sound captions (no audio)"}, true);
button({hu: "Újrajátszás", en: "Replay"}, reset);

let tc = 0;                                            // cutscene time (s): the only state variable
update(dt => { tc += dt; });                           // everything else is a function of tc

// ---------- small helpers ----------
function sstep(a, b, x) {                              // smooth 0→1 ramp between times a and b
  const k = clamp((x - a) / (b - a), 0, 1);
  return k * k * (3 - 2 * k);
}
function hash(i, j) {                                  // repeatable pseudo-random number 0…1 (for stains, board colours)
  const s = sin(i * 12.9898 + j * 78.233) * 43758.5453;
  return s - floor(s);
}
const add3 = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const sub3 = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot3 = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

// A face = {p: corner points [x,y,z] in metres, c: colour [r,g,b] 0…255, a: self-light 0…1+,
//           b: sort bias (bigger = drawn later, i.e. "in front"), al: opacity}
function quad(list, pts, col, amb, bias) { list.push({p: pts, c: col, a: amb || 0, b: bias || 0, al: 1}); }

// A flat surface split into nu × nv tiles. o = corner, uF and vF = the two full side vectors.
// fn(i, j) returns [colour, self-light] for tile (i, j). Small tiles keep the depth sorting correct.
function tiles(list, o, uF, vF, nu, nv, fn, bias) {
  const pt = (fi, fj) => [o[0] + uF[0] * fi / nu + vF[0] * fj / nv,
                          o[1] + uF[1] * fi / nu + vF[1] * fj / nv,
                          o[2] + uF[2] * fi / nu + vF[2] * fj / nv];
  for (let j = 0; j < nv; j++) for (let i = 0; i < nu; i++) {
    const r = fn(i, j);
    list.push({p: [pt(i, j), pt(i + 1, j), pt(i + 1, j + 1), pt(i, j + 1)], c: r[0], a: r[1], b: bias || 0, al: 1});
  }
}

// A box: centre c, size s = [sx, sy, sz] (m), turned by ang (rad) about the vertical axis.
function cuboid(list, c, s, ang, col, amb, bias) {
  const ca = cos(ang), sa = sin(ang), V = [];
  for (const sx of [-1, 1]) for (const sy of [-1, 1]) for (const sz of [-1, 1]) {
    const x = sx * s[0] / 2, z = sz * s[2] / 2;
    V.push([c[0] + x * ca + z * sa, c[1] + sy * s[1] / 2, c[2] - x * sa + z * ca]);
  }
  const F = [[0, 1, 3, 2], [4, 5, 7, 6], [0, 1, 5, 4], [2, 3, 7, 6], [0, 2, 6, 4], [1, 3, 7, 5]];
  const SH = [0.85, 1, 0.6, 1.1, 0.8, 0.95];            // each side a bit lighter/darker = looks 3D
  for (let k = 0; k < 6; k++)
    list.push({p: F[k].map(i => V[i]), c: col.map(x => x * SH[k]), a: amb || 0, b: bias || 0, al: 1});
}

// Wallpaper tile colour: faded yellow with dark damp stains
function wallCol(i, j, seed) {
  const h = hash(i + seed, j * 1.7);
  if (h > 0.82) return [[48, 40, 32], 0];
  return [[96 + 24 * h, 84 + 20 * h, 64 + 14 * h], 0];
}

// ---------- THE HOUSE (built once) ----------
// Coordinates: x right, y up, z towards the viewer. The hallway runs from z = +2 to z = −14 (3 m wide, 3 m high);
// the haunted room lies beyond the door at z = −14 (8 m wide, z = −14 … −23).
const S = [];                                          // all static faces
// hallway
tiles(S, [-1.5, 0, 2], [3, 0, 0], [0, 0, -16], 3, 16, (i, j) => { const h = hash(i, j); return [[60 + 40 * h, 42 + 28 * h, 30 + 18 * h], 0]; });   // floor boards
tiles(S, [-1.5, 3, 2], [3, 0, 0], [0, 0, -16], 3, 16, (i, j) => { const h = hash(i + 3, j); return [[70 + 20 * h, 66 + 18 * h, 60 + 16 * h], 0]; }); // ceiling
tiles(S, [-1.5, 0, 2], [0, 3, 0], [0, 0, -16], 3, 16, (i, j) => wallCol(i, j, 0));      // left wall
tiles(S, [1.5, 0, 2], [0, 3, 0], [0, 0, -16], 3, 16, (i, j) => wallCol(i, j, 40));      // right wall
// end wall of the hallway with a door opening (x −0.6 … 0.6, height 2.2 m)
tiles(S, [-1.5, 0, -14], [0.9, 0, 0], [0, 3, 0], 3, 6, (i, j) => wallCol(i, j, 11));
tiles(S, [0.6, 0, -14], [0.9, 0, 0], [0, 3, 0], 3, 6, (i, j) => wallCol(i, j, 23));
tiles(S, [-0.6, 2.2, -14], [1.2, 0, 0], [0, 0.8, 0], 4, 2, (i, j) => wallCol(i, j, 31));
cuboid(S, [-0.63, 1.1, -14], [0.08, 2.2, 0.2], 0, [40, 30, 22], 0, 0.1);     // door frame, left
cuboid(S, [0.63, 1.1, -14], [0.08, 2.2, 0.2], 0, [40, 30, 22], 0, 0.1);      // door frame, right
cuboid(S, [0, 2.24, -14], [1.34, 0.08, 0.2], 0, [40, 30, 22], 0, 0.1);       // door frame, top
// creepy portrait on the left wall at z = −4 (the camera stops here and looks at it)
cuboid(S, [-1.47, 1.8, -4], [0.06, 1.0, 0.8], 0, [70, 52, 30], 0);           // frame
quad(S, [[-1.435, 1.35, -3.65], [-1.435, 1.35, -4.35], [-1.435, 2.25, -4.35], [-1.435, 2.25, -3.65]], [34, 30, 26], 0, 0.1);   // canvas
{
  const oval = (cy, cz, ry, rz, n) => { const o = []; for (let k = 0; k < n; k++) { const a = 2 * PI * k / n; o.push([-1.43, cy + ry * sin(a), cz + rz * cos(a)]); } return o; };
  quad(S, oval(1.85, -4, 0.28, 0.17, 12), [178, 168, 150], 0, 0.15);        // pale face
  quad(S, oval(1.93, -4.07, 0.035, 0.035, 6), [5, 5, 5], 0, 0.2);           // eyes: two black holes
  quad(S, oval(1.93, -3.93, 0.035, 0.035, 6), [5, 5, 5], 0, 0.2);
  quad(S, oval(1.70, -4, 0.025, 0.06, 8), [5, 5, 5], 0, 0.2);               // mouth
}
cuboid(S, [1.47, 1.7, -8], [0.06, 0.9, 0.7], 0.0, [60, 45, 28], 0);          // an empty frame on the right wall
// furniture and rubbish in the hallway
cuboid(S, [1.2, 0.5, -3], [0.6, 1.0, 1.4], 0, [58, 42, 30], 0);              // old dresser against the right wall
cuboid(S, [0.85, 0.28, -6.5], [0.06, 0.5, 0.5], 0, [70, 50, 32], 0);         // toppled chair: seat standing up…
cuboid(S, [0.55, 0.04, -6.5], [0.6, 0.06, 0.5], 0.3, [70, 50, 32], 0);       // …and its back lying on the floor
for (let k = 0; k < 8; k++)                                                  // debris on the floor
  cuboid(S, [-1.1 + 2.2 * hash(k, 1), 0.04, -2 - 11 * hash(k, 2)], [0.15 + 0.2 * hash(k, 3), 0.08, 0.1 + 0.2 * hash(k, 4)],
         6 * hash(k, 5), [50, 42, 34], 0);
// the room
tiles(S, [-4, 0, -14], [8, 0, 0], [0, 0, -9], 8, 9, (i, j) => {
  if (i >= 1 && i <= 2 && j >= 6 && j <= 8) return [[120, 128, 150], 0.4];  // patch of moonlight on the floor
  const h = hash(i + 7, j); return [[62 + 36 * h, 46 + 26 * h, 34 + 16 * h], 0];
});
tiles(S, [-4, 3, -14], [8, 0, 0], [0, 0, -9], 8, 9, (i, j) => { const h = hash(i + 5, j + 2); return [[66 + 20 * h, 62 + 18 * h, 58 + 16 * h], 0]; });   // ceiling
tiles(S, [-4, 0, -14], [0, 3, 0], [0, 0, -9], 3, 9, (i, j) => wallCol(i, j, 51));    // left wall
tiles(S, [4, 0, -14], [0, 3, 0], [0, 0, -9], 3, 9, (i, j) => wallCol(i, j, 61));     // right wall
tiles(S, [-4, 0, -23], [8, 0, 0], [0, 3, 0], 8, 3, (i, j) => wallCol(i, j, 71));     // back wall
tiles(S, [-4, 0, -14], [2.5, 0, 0], [0, 3, 0], 3, 3, (i, j) => wallCol(i, j, 81));   // front wall, left part
tiles(S, [1.5, 0, -14], [2.5, 0, 0], [0, 3, 0], 3, 3, (i, j) => wallCol(i, j, 91));  // front wall, right part
quad(S, [[-3.2, 1, -22.99], [-1.8, 1, -22.99], [-1.8, 2.4, -22.99], [-3.2, 2.4, -22.99]], [150, 175, 230], 1, 0.2);   // window = moonlight
cuboid(S, [-2.5, 1.7, -22.95], [0.05, 1.4, 0.04], 0, [20, 18, 22], 0, 0.3);  // window cross bars
cuboid(S, [-2.5, 1.7, -22.95], [1.4, 0.05, 0.04], 0, [20, 18, 22], 0, 0.3);
for (const sx of [-1, 1]) for (const sz of [-1, 1])                           // iron bed: four posts…
  cuboid(S, [3 + 0.58 * sx, 0.45, -19 + 1.0 * sz], [0.06, 0.9, 0.06], 0, [30, 28, 32], 0);
cuboid(S, [3, 0.5, -19], [1.1, 0.25, 2.0], 0, [96, 88, 70], 0);              // …and a stained mattress
cuboid(S, [-3.4, 1.1, -21.9], [1.3, 2.2, 0.9], 0.2, [50, 36, 26], 0);        // wardrobe in the corner
cuboid(S, [-1.5, 0.22, -16.5], [0.5, 0.06, 0.5], 0.5, [66, 48, 32], 0);      // chair seat…
cuboid(S, [-1.5, 0.55, -16.7], [0.5, 0.6, 0.05], 0.5, [66, 48, 32], 0);      // …and back

// ---------- DYNAMIC PARTS (rebuilt every frame) ----------
// The door swings about its hinge at (−0.6, −14): ao = opening angle (rad), swinging into the room.
function addDoor(list, ao) {
  const hx = -0.6, hz = -14, w = 1.2, h = 2.2;
  const ex = hx + w * cos(ao), ez = hz - w * sin(ao);                         // free edge of the door
  tiles(list, [hx, 0, hz], [ex - hx, 0, ez - hz], [0, h, 0], 3, 4, (i, j) => {
    const hh = hash(i + 9, j + 3), panel = (i === 1 && (j === 1 || j === 2)); // recessed wooden panels
    return [[panel ? 54 : 70 + 16 * hh, panel ? 38 : 50 + 10 * hh, panel ? 28 : 38 + 8 * hh], 0];
  }, 0.15);
  cuboid(list, [hx + (w - 0.1) * cos(ao), 1.0, hz - (w - 0.1) * sin(ao)], [0.07, 0.07, 0.07], 0, [170, 150, 70], 0, 0.3);   // knob
}

// The ghost: ragged robe, long black hair, hollow eyes, hanging arms.
// (gx, gy, gz) = floor point under the ghost, yawH = head turn (0 = face towards the viewer, π = away),
// u = 0…1 lunge/scream intensity, tt = time.
function addGhost(list, gx, gy, gz, yawH, u, tt) {
  const GC = [200, 214, 232];                          // pale blue-white
  const NS = 10, NL = 6;                               // 10 segments around, 6 levels up
  const scl = 1 - 0.35 * u;                            // the robe narrows as it lunges
  const R = [];
  for (let j = 0; j <= NL; j++) {                      // level 0 = torn hem, level NL = shoulders
    const hf = j / NL, rad = (0.62 - 0.36 * hf) * scl, ox = 0.07 * hf * sin(1.3 * tt + 2 * hf);
    const row = [];
    for (let k = 0; k <= NS; k++) {
      const a = 2 * PI * k / NS;
      const rr = rad + (j === 0 ? 0.09 * sin(3 * a + 2.5 * tt) : 0.03 * sin(2 * a + tt + j));   // waving cloth
      const yy = gy + 1.5 * hf + (j === 0 ? 0.14 * sin(5 * a + 1.7 * tt) : 0);                  // ragged hem
      row.push([gx + ox + rr * cos(a), yy, gz + rr * sin(a)]);
    }
    R.push(row);
  }
  for (let j = 0; j < NL; j++) for (let k = 0; k < NS; k++) {
    const sh = 0.55 + 0.45 * (j + 0.5) / NL;           // darker and more see-through towards the hem
    list.push({p: [R[j][k], R[j][k + 1], R[j + 1][k + 1], R[j + 1][k]], c: GC.map(x => x * sh), a: 1.1, b: 0, al: 0.55 + 0.4 * (j + 1) / NL});
  }
  // head (an egg-shaped mesh)
  const hx = gx + 0.07 * sin(1.3 * tt + 2), hy = gy + 1.78, hz = gz;
  const NA = 8, NB = 5, H = [];
  for (let m = 0; m <= NB; m++) {
    const th = PI * m / NB, row = [];
    for (let k = 0; k <= NA; k++) { const a = 2 * PI * k / NA; row.push([hx + 0.2 * sin(th) * cos(a), hy + 0.27 * cos(th), hz + 0.2 * sin(th) * sin(a)]); }
    H.push(row);
  }
  for (let m = 0; m < NB; m++) for (let k = 0; k < NA; k++)
    list.push({p: [H[m][k], H[m][k + 1], H[m + 1][k + 1], H[m + 1][k]], c: [215, 226, 238], a: 1.15, b: 0, al: 0.95});
  // face features sit on the front of the head; fx, fz = facing direction, rx, rz = the head's right side
  const fx = sin(yawH), fz = cos(yawH), rx = cos(yawH), rz = -sin(yawH);
  const at = (a, b, d) => [hx + rx * a + fx * d, hy + b, hz + rz * a + fz * d];
  for (const s of [-1, 1]) {
    const cxE = 0.075 * s, cyE = 0.04, wxE = 0.045 * (1 + 0.3 * u), wyE = 0.065 * (1 + 1.2 * u);   // sockets stretch when screaming
    const eye = [], pup = [];
    for (let k = 0; k < 8; k++) { const a = 2 * PI * k / 8; eye.push(at(cxE + wxE * cos(a), cyE + wyE * sin(a), 0.195)); }
    for (let k = 0; k < 6; k++) { const a = 2 * PI * k / 6; pup.push(at(cxE + 0.014 * cos(a), cyE + 0.014 * sin(a), 0.2)); }
    list.push({p: eye, c: [3, 3, 5], a: 0, b: 0.07, al: 1});          // black hollow eye
    list.push({p: pup, c: [255, 90, 90], a: 1.2, b: 0.09, al: 1});    // tiny glowing red pupil
  }
  const mh = 0.012 + 0.11 * u, mw = 0.04 * (1 + 0.9 * u), my = -0.1 - 0.05 * u, mp = [];   // mouth opens into a scream
  for (let k = 0; k < 10; k++) { const a = 2 * PI * k / 10; mp.push(at(mw * cos(a), my + mh * sin(a), 0.195)); }
  list.push({p: mp, c: [8, 0, 2], a: 0, b: 0.07, al: 1});
  // long black hair strands hanging round the head (they fly up during the lunge)
  for (const ph of [-2.6, -2.0, -1.5, -0.95, 0.95, 1.5, 2.0, 2.6, 3.1]) {
    const dxn = fx * cos(ph) + rx * sin(ph), dzn = fz * cos(ph) + rz * sin(ph);   // direction away from the head centre
    const px = -dzn, pz = dxn;                                                    // sideways (strand width direction)
    const top = [hx + dxn * 0.2, hy + 0.17, hz + dzn * 0.2];
    const bot = [hx + dxn * (0.27 + 0.4 * u) + 0.05 * sin(1.1 * tt + ph * 3), hy - 1.0 + 1.5 * u, hz + dzn * (0.27 + 0.4 * u)];
    list.push({p: [[top[0] - px * 0.035, top[1], top[2] - pz * 0.035], [top[0] + px * 0.035, top[1], top[2] + pz * 0.035],
                   [bot[0] + px * 0.06, bot[1], bot[2] + pz * 0.06], [bot[0] - px * 0.06, bot[1], bot[2] - pz * 0.06]],
               c: [7, 7, 10], a: 0, b: 0.04, al: 1});
  }
  // arms: hang down at rest, reach towards the viewer when u → 1
  for (const s of [-1, 1]) {
    const shoulder = [gx + 0.06 * sin(1.3 * tt + 1.8) + 0.26 * s * scl, gy + 1.38, gz + 0.02];
    const hand = [gx + s * (0.4 - 0.1 * u), gy + 0.55 + 0.95 * u, gz + 0.05 + 0.8 * u];
    for (const wv of [[0.05, 0, 0], [0, 0, 0.05]])
      list.push({p: [sub3(shoulder, wv), add3(shoulder, wv), add3(hand, wv), sub3(hand, wv)], c: GC.map(x => x * 0.85), a: 1.1, b: 0, al: 0.9});
    for (let f = 0; f < 4; f++) {                                                // four long fingers
      const o2 = (f - 1.5) * 0.03, base = [hand[0] + o2, hand[1], hand[2]];
      const tip = [hand[0] + o2 * 1.6, hand[1] - 0.2 * (1 - u), hand[2] + 0.28 * u];
      const wv = u < 0.5 ? [0.014, 0, 0] : [0, 0.014, 0];
      list.push({p: [sub3(base, wv), add3(base, wv), add3(tip, wv), sub3(tip, wv)], c: [226, 232, 240], a: 1.15, b: 0.03, al: 1});
    }
  }
}

// ---------- CAMERA PATH, LIGHT, CAPTIONS ----------
// Distance along the hallway (camera z): walk 1 → −4, stop at the portrait, walk on to −11.5, creep to −12.8 at the door.
function zAt(tt) { return 1 - 5 * sstep(0, 6, tt) - 7.5 * sstep(9.3, 16, tt) - 1.3 * sstep(20.5, 25.5, tt); }
// the flashlight dies for short moments (the ghost moves closer each time it is dark)
const OFFS = [[10.3, 10.42], [13.7, 13.82], [22.0, 22.25], [23.4, 23.65], [24.8, 25.05], [25.75, 25.95]];
function lampLevel(tt) {
  for (const w of OFFS) if (tt > w[0] && tt < w[1]) return 0.04;     // off (a faint glow remains)
  return 0.92 + 0.08 * sin(37 * tt) * sin(11 * tt);                  // slight flicker
}
const CAP = [
  [0.8, 6, {hu: "[Padló nyikorog]", en: "[Floorboards creak]"}],
  [6.2, 9.2, {hu: "[Halk suttogás a falból]", en: "[Faint whispering inside the wall]"}],
  [9.4, 16, {hu: "[Lassú, nehéz léptek]", en: "[Slow, heavy footsteps]"}],
  [16.5, 22, {hu: "[Az ajtó nyikorogva kinyílik]", en: "[The door creaks open]"}],
  [22.3, 25.7, {hu: "[Csend…]", en: "[Silence…]"}],
  [26, 27.4, {hu: "[ÜVÖLTÉS]", en: "[SCREAM]"}]
];
const NEAR = 0.1;                                      // near clipping plane (m)

// ---------- 2) DRAWING ----------
draw(t => {
  const J = P.jump;
  // --- camera: position (camX, camY, camZ), turn yaw, nod pitch (rad) ---
  const spd = abs(zAt(tc + 0.05) - zAt(tc - 0.05)) / 0.1;          // walking speed (m/s)
  const sw = clamp(spd / 0.8, 0, 1);                               // 0 = standing, 1 = walking
  const ph = -zAt(tc) / 0.75 * 2 * PI;                             // stride phase: one step every 0.75 m
  const look = sstep(6.1, 7.6, tc) * (1 - sstep(8.0, 9.2, tc));    // 0…1…0: glance at the portrait
  let camX = P.bob * sw * 0.03 * sin(ph / 2);                      // sway left-right (once per two steps)
  let camY = 1.65 + P.bob * sw * 0.04 * sin(ph) + 0.006 * sin(1.7 * tc);   // eye height + step bounce + breathing
  let camZ = zAt(tc);
  let yaw = -deg(80) * look + 0.012 * sin(0.9 * tc) + 0.006 * sin(2.3 * tc + 1);   // negative = turn left; + handheld drift
  let pitch = deg(-3) + deg(6) * look + P.bob * sw * 0.01 * sin(ph + 1) + 0.006 * sin(1.3 * tc);
  // jumpscare reaction: lunge progress uu (accelerating), flinch back rc, shake sh
  const uu = J ? pow(clamp((tc - 26) / 0.35, 0, 1), 2) : 0;
  const rc = J ? sstep(26.15, 26.6, tc) * (1 - sstep(27, 28, tc)) : 0;
  camZ += 0.2 * rc; pitch += 0.2 * rc; yaw += 0.05 * rc;
  const sh = (J && tc > 26.1) ? 0.07 * exp(-(tc - 26.1) * 1.6) : 0;
  camX += sh * sin(61 * tc); camY += sh * cos(53 * tc);
  yaw += 0.6 * sh * sin(47 * tc + 1); pitch += 0.6 * sh * sin(43 * tc);
  const fl = lerp(520, 1000, uu);                                  // focal length (px): zooms in during the scream

  // camera axes in the world: right Rv, up Uv, forward Fv
  const Rv = [cos(yaw), 0, sin(yaw)];
  const Fv = [sin(yaw) * cos(pitch), sin(pitch), -cos(yaw) * cos(pitch)];
  const Uv = [-sin(yaw) * sin(pitch), cos(pitch), cos(yaw) * sin(pitch)];

  // --- ghost and door state ---
  let gz0 = -20.5;                                                 // it steps closer while the light is off
  if (tc > 22.125) gz0 = -19;
  if (tc > 23.525) gz0 = -17.5;
  if (tc > 24.925) gz0 = -16;
  const gzNow = lerp(gz0, zAt(26) - 1.05, uu);                     // the lunge ends ~1 m in front of the camera
  const gyNow = lerp(0.3 + 0.05 * sin(1.5 * tc), 0, uu);           // it floats just above the floor
  const yawH = PI * (1 - sstep(25.3, 25.9, tc)) + 0.05 * sin(tc);  // head slowly turns from the wall towards you
  const ao = 1.75 * sstep(16.5, 21.5, tc) + 0.03 * sin(3 * tc) * sstep(16.5, 17, tc) * (1 - sstep(21.5, 22, tc));   // door angle

  const D = [];
  addDoor(D, ao);
  addGhost(D, 0, gyNow, gzNow, yawH, uu, tc);
  const all = S.concat(D);

  // --- project every face: world → camera space → near-clip → screen ---
  const lampOn = lampLevel(tc) * P.lamp;
  const items = [];
  for (const f of all) {
    let v = f.p.map(p => { const q = sub3(p, [camX, camY, camZ]); return [dot3(q, Rv), dot3(q, Uv), dot3(q, Fv)]; });
    let behind = 0;
    for (const q of v) if (q[2] < NEAR) behind++;
    if (behind === v.length) continue;                             // completely behind the camera
    if (behind > 0) {                                              // cut the part that is behind the near plane
      const out = [];
      for (let i = 0; i < v.length; i++) {
        const a = v[i], b = v[(i + 1) % v.length], ina = a[2] >= NEAR, inb = b[2] >= NEAR;
        if (ina) out.push(a);
        if (ina !== inb) { const k = (NEAR - a[2]) / (b[2] - a[2]); out.push([a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, NEAR]); }
      }
      v = out;
      if (v.length < 3) continue;
    }
    let cx = 0, cy = 0, cz = 0;
    for (const q of v) { cx += q[0]; cy += q[1]; cz += q[2]; }
    cx /= v.length; cy /= v.length; cz /= v.length;                // centroid in camera space
    const pts = v.map(q => [500 + fl * q[0] / q[2], 300 - fl * q[1] / q[2]]);
    let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
    for (const q of pts) { x0 = min(x0, q[0]); x1 = max(x1, q[0]); y0 = min(y0, q[1]); y1 = max(y1, q[1]); }
    if (x1 < -20 || x0 > 1020 || y1 < -20 || y0 > 620) continue;  // off-screen
    items.push({pts, key: cz - f.b, f, cx, cy, cz});
  }
  items.sort((a, b) => b.key - a.key);                             // painter's algorithm: far faces first

  // --- shade and draw ---
  for (const it of items) {
    const d = sqrt(it.cx * it.cx + it.cy * it.cy + it.cz * it.cz);          // distance camera → face
    const cone = clamp((it.cz / d - 0.45) / 0.45, 0, 1);                    // flashlight beam: bright in the centre of the view
    const flash = lampOn * cone / (1 + 0.03 * d * d);                       // light fades with distance (1/(1+k·d²))
    const c = it.f.c, am = it.f.a;
    const r = floor(clamp(c[0] * (flash * 1.00 + am * 0.8 + 0.030), 0, 255));   // warm torch light, cold moonlight/ghost glow
    const g = floor(clamp(c[1] * (flash * 0.96 + am * 0.9 + 0.040), 0, 255));
    const b = floor(clamp(c[2] * (flash * 0.88 + am * 1.1 + 0.055), 0, 255));
    const col = `rgb(${r},${g},${b})`;
    if (it.f.al < 0.999) polygon(it.pts, {fill: col, stroke: null, alpha: it.f.al});
    else polygon(it.pts, {fill: col, stroke: col, lw: 1});                  // same-colour outline hides hairline gaps
  }

  // --- film look: grain, vignette, letterbox ---
  for (let k = 0; k < 60; k++) rect(random() * 1000, random() * 600, 2, 2, {fill: "#fff", stroke: null, alpha: 0.05});
  for (let k = 0; k < 6; k++) ring(500, 300, 360 + k * 55, 440 + k * 55, {fill: "#000", stroke: null, alpha: 0.2});
  if (P.bars) { rect(0, 0, 1000, 55, {fill: "#000", stroke: null}); rect(0, 545, 1000, 55, {fill: "#000", stroke: null}); }

  // --- jumpscare overlays ---
  const flashW = J ? sstep(26.28, 26.34, tc) * (1 - sstep(26.34, 26.7, tc)) * 0.9 : 0;   // one short white flash
  if (flashW > 0.002) rect(0, 0, 1000, 600, {fill: "#fff", stroke: null, alpha: flashW});
  const redA = J ? 0.28 * sstep(26.34, 26.5, tc) * (1 - sstep(27, 27.6, tc)) : 0;
  if (redA > 0.002) rect(0, 0, 1000, 600, {fill: "#a00010", stroke: null, alpha: redA});
  const blk = max(1 - sstep(0, 1.6, tc), J ? sstep(27.2, 27.9, tc) : 0);                   // fade in at the start, cut to black after the scare
  if (blk > 0.002) rect(0, 0, 1000, 600, {fill: "#000", stroke: null, alpha: blk});

  // --- captions and end card ---
  if (P.caps) for (const c of CAP) if (tc > c[0] && tc < c[1] && (c[0] < 26 || J))
    text(c[2], 500, 578, {size: 20, color: "#d8d2e0", align: "center", italic: true});
  if (J && tc > 28.6) {
    const ea = sstep(28.6, 29.6, tc);
    text({hu: "Nem vagy egyedül.", en: "You are not alone."}, 500, 300, {size: 48, bold: true, color: "#c8c0d0", align: "center", alpha: ea});
    text({hu: "(Újrajátszás: R)", en: "(Replay: R)"}, 500, 345, {size: 18, color: "#7a7482", align: "center", alpha: ea});
  }

  // --- readouts and graphs ---
  const phase = tc < 6 ? {hu: "Séta a folyosón", en: "Walking the hallway"} : tc < 9.3 ? {hu: "A festmény", en: "The portrait"}
              : tc < 16.5 ? {hu: "Közelít az ajtóhoz", en: "Approaching the door"} : tc < 21.5 ? {hu: "Az ajtó nyílik", en: "The door opens"}
              : tc < 26 ? {hu: "A szoba", en: "The room"} : {hu: "…", en: "…"};
  const gDist = sqrt((0 - camX) * (0 - camX) + (gzNow - camZ) * (gzNow - camZ));
  show({hu: "Idő", en: "Time"}, tc, "s", 1);
  show({hu: "Jelenet", en: "Scene"}, tr(phase), "", 0);
  show({hu: "Kamera z", en: "Camera z"}, camZ, "m", 1);
  show({hu: "Szellem távolsága", en: "Ghost distance"}, gDist, "m", 1);
  plot({hu: "Járás sebessége", en: "Walking speed"}, spd, {unit: "m/s", color: C.teal, min: 0});
  plot({hu: "Szellem távolsága", en: "Ghost distance"}, gDist, {unit: "m", color: C.red, min: 0});
});
